WITH cleaned AS (SELECT *, SUBSTRING(event_type, 1, 2) AS event_type_prefix, COALESCE(page, 'OTHER') AS page_clean FROM web_events WHERE page IS NOT NULL), enriched AS (SELECT *, LAST_VALUE(page) IGNORE NULLS OVER w_hist AS last_known_page, FIRST_VALUE(page, TRUE) OVER w_part AS first_known_page FROM cleaned WINDOW w_hist AS (ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_part AS (PARTITION BY session_id ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), remaining_keys AS (SELECT id, page FROM enriched EXCEPT SELECT id, page FROM web_events WHERE HOUR(event_time) BETWEEN 6 AND 10), kept_rows AS (SELECT s.* FROM enriched s INNER JOIN remaining_keys k ON s.id = k.id AND s.page = k.page), enriched_web_events AS (SELECT *, DENSE_RANK() OVER (PARTITION BY session_id, page ORDER BY duration_sec) AS duration_sec_dense_rank, COUNT(duration_sec) OVER (PARTITION BY session_id) AS session_id_count_duration_sec FROM kept_rows) SELECT id, session_id, event_type, page, event_time, duration_sec, event_type_prefix, page_clean, last_known_page FROM enriched_web_events;
